// packages/core/src/state.ts — PURE. No I/O, no timers, no instance access.
export type State =
  | 'disabled' | 'idle' | 'connecting' | 'discovering' | 'ready'
  | 'retrying' | 'authRequired' | 'failed' | 'stopping' | 'closed';

export type Ev =
  | { t: 'start' }
  | { t: 'connectOk' }
  | { t: 'connectFail';  err: Error; permanent: boolean }
  | { t: 'discoverOk';   catalog: ServerCatalog }
  | { t: 'discoverFail'; err: Error; permanent: boolean }
  | { t: 'authChallenge'; authorizationUrl?: string }
  | { t: 'authResolved' }
  | { t: 'transportClose'; err?: Error }
  | { t: 'backoffElapsed' }
  | { t: 'giveUp' }
  | { t: 'refresh' }
  | { t: 'enable' }
  | { t: 'disable' }
  | { t: 'stop'; intent: 'closed' | 'disabled' | 'idle' }
  | { t: 'stopped' };

const FAIL = '@fail' as const;            // -> ev.permanent ? 'failed' : 'retrying'
const INTENT = '@intent' as const;        // -> the intent captured at `stop`

export const TABLE: Record<State, Partial<Record<Ev['t'], State | '@fail' | '@intent'>>> = {
  //  state          legal events -> next
  disabled:     { enable: 'idle', stop: 'closed' },
  idle:         { start: 'connecting', disable: 'disabled', stop: 'closed' },
  connecting:   { connectOk: 'discovering', connectFail: FAIL,
                  transportClose: 'retrying', authChallenge: 'authRequired',
                  stop: 'stopping', disable: 'stopping' },
  discovering:  { discoverOk: 'ready', discoverFail: FAIL,
                  transportClose: 'retrying', authChallenge: 'authRequired',
                  stop: 'stopping', disable: 'stopping' },
  ready:        { refresh: 'ready', transportClose: 'retrying',
                  authChallenge: 'authRequired',
                  stop: 'stopping', disable: 'stopping' },
  retrying:     { backoffElapsed: 'connecting', giveUp: 'failed',
                  stop: 'closed', disable: 'disabled' },
  authRequired: { authResolved: 'connecting', start: 'connecting',
                  stop: 'closed', disable: 'disabled' },
  failed:       { start: 'connecting', stop: 'closed', disable: 'disabled' },
  stopping:     { stopped: INTENT },       // every other event is dropped
  closed:       { },                       // TERMINAL: absorbs everything
};

/** undefined => illegal pair => DROP (debug log). Never throws. */
export function next(s: State, ev: Ev, intent: State): State | undefined {
  const to = TABLE[s][ev.t];
  if (!to) return undefined;
  if (to === FAIL)   return (ev as { permanent: boolean }).permanent ? 'failed' : 'retrying';
  if (to === INTENT) return intent;
  return to;
}

// packages/core/src/index.ts — the ONLY object packages/server holds.
export class Engine {
  constructor(opts: EngineOptions);
  readonly events: Bus<EngineEvents>;

  /** Idempotent full-state diff. The only mutator. Safe to call on every config write. */
  applyConfig(configs: ServerConfig[]): Promise<void>;

  listTools(scope: ResolvedScope, principal: Principal): Promise<Tool[]>;
  listPrompts(scope: ResolvedScope, principal: Principal): Promise<Prompt[]>;
  listResources(scope: ResolvedScope, principal: Principal): Promise<Resource[]>;
  listResourceTemplates(scope: ResolvedScope, principal: Principal): Promise<ResourceTemplate[]>;

  callTool(req: CallToolReq): Promise<CallToolResult>;
  getPrompt(req: GetPromptReq): Promise<GetPromptResult>;
  readResource(req: ReadResourceReq): Promise<ReadResourceResult>;

  /** Everything the dashboard needs. Cheap, synchronous, no upstream I/O. */
  status(): ServerStatus[];
  /** Raw per-server catalog for context-cost + embedding sync. Descriptions already overridden. */
  catalog(serverName: string): ServerCatalog | undefined;
  /** Operator action: force reconnect of one server (resets the attempt counter). */
  reload(serverName: string): Promise<void>;
  shutdown(): Promise<void>;
}

export type EngineOptions = {
  logger: Logger;                                   // pino child, injected
  connect?: TransportFactory;                       // default: the real one. TEST SEAM.
  authProviderFor?: (c: ServerConfig) => OAuthClientProvider | undefined;
  connectConcurrency?: number;                      // default 8
  defaults?: { connectMs?: number; requestMs?: number; maxConcurrentCalls?: number };
};

export type CallToolReq = {
  scope: ResolvedScope;
  principal: Principal;
  name: string;                                     // downstream name, prefixed/aliased/flattened
  args: Record<string, unknown>;
  signal?: AbortSignal;                             // client disconnect === cancellation
  onProgress?: (p: { progress: number; total?: number; message?: string }) => void;
  deadlineMs?: number;                              // default 60_000
};

// packages/core/src/types.ts — the contract packages/server must satisfy.
export type ServerSelection = {
  serverName: string;
  alias?: string;                       // renames the server on this route only
  tools:     'all' | string[];          // BARE upstream names
  prompts:   'all' | string[];
  resources: 'all' | string[];
};

export type ResolvedScope = {
  /** Stable memo key. MUST be a pure function of the fields below. server package computes it. */
  key: string;
  /** Already authorized. Core does NO authz. An empty array means an empty catalog, never 'all'. */
  servers: ServerSelection[];
  /** Single-server route: strip the `<server>__` prefix. Set only when servers.length === 1. */
  flatten: boolean;
};

export type Principal = {
  id: string;                           // user id, or the api-key owner's user id
  isAdmin: boolean;
  /** Present ONLY when this auth path is permitted to use per-user secrets. */
  credentials?: CredentialResolver;
};

export interface CredentialResolver {
  /** Returns {} when this principal has no binding for this server. Never throws for 'missing'. */
  resolveHeaders(serverName: string): Promise<Record<string, string>>;
  /** Opaque, changes when the underlying binding changes. Used as the connection key suffix. */
  revision(serverName: string): string;
}

// Owned by the persistence subsystem's zod schema; core imports the type only.
export type ServerConfig = {
  name: string;            // ^[A-Za-z0-9](?:[A-Za-z0-9_-]{0,62}[A-Za-z0-9])?$  AND  !name.includes(SEP)
  enabled: boolean;
  credentialMode: 'shared' | 'per-user';
  /** Keys are BARE upstream tool names, normalized at write time. Core rejects any key with SEP. */
  tools?: Record<string, { enabled?: boolean; description?: string }>;
  timeouts?: { connectMs?: number; requestMs?: number };
  maxConcurrentCalls?: number;                                  // default 64
} & (
  | { type: 'stdio'; command: string; args?: string[];
      env?: Record<string, string>; cwd?: string }
  | { type: 'streamable-http' | 'sse'; url: string;
      headers?: Record<string, string>;
      /** Explicit, audited SSRF escape hatch. There is NO owner-based bypass. */
      allowPrivateNetwork?: boolean }
);

export const SEP = '__';   // not configurable. See D6.

// packages/core/src/upstream-server.ts — one per (serverName, credential fingerprint).
export class UpstreamServer {
  readonly key: string;           // `${name}` | `${name}#${principalId}:${credRevision}`
  readonly name: string;
  readonly configHash: string;    // sha256 of the normalized config; drives the applyConfig diff
  get state(): State;
  get catalog(): ServerCatalog | undefined;   // immutable snapshot, swapped atomically
  get stale(): boolean;           // ready-cache being served while reconnecting (D14)
  get stderrTail(): readonly string[];        // bounded ring, 200 lines

  start(): void;                                       // fire-and-forget; state -> connecting
  /** ready -> resolve; failed|disabled|closed -> throw; idle -> start() then wait. */
  ensureReady(deadlineMs?: number): Promise<void>;
  stop(intent: 'closed' | 'disabled' | 'idle'): Promise<void>;
  refresh(): void;                                     // upstream listChanged -> recache

  callTool(bare: string, args: unknown, o: CallOpts): Promise<CallToolResult>;
  getPrompt(bare: string, args: unknown, o: CallOpts): Promise<GetPromptResult>;
  readResource(uri: string, o: CallOpts): Promise<ReadResourceResult>;

  /** THE only mutator of `state`. Table-driven, drops illegal pairs, checks epoch. */
  private dispatch(ev: Ev): void;
  private epoch = 0;              // identity guard for async continuations (D3)
}

export type ServerCatalog = {
  tools: ReadonlyMap<string, Tool>;               // keyed by BARE name, description already overridden
  prompts: ReadonlyMap<string, Prompt>;
  resources: readonly Resource[];
  resourceTemplates: readonly ResourceTemplate[];
  capabilities: ServerCapabilities;
  instructions?: string;
  fetchedAt: number;
  namesHash: string;                              // drives server:catalog{changed}
};

// packages/core/src/registry.ts
export class ServerRegistry {
  readonly generation: number;        // ++ per applyConfig
  readonly catalogVersion: number;    // ++ per applyConfig OR any server:catalog emit

  /** Diff by name + configHash. Unchanged servers are NOT touched. */
  async applyConfig(configs: ServerConfig[]): Promise<void> {
    // added    -> new UpstreamServer(...).start()
    // changed  -> old.stop('closed'); new UpstreamServer(...).start()
    // removed  -> old.stop('closed'); map.delete()
    // toggled  -> dispatch({t:'enable'|'disable'})
    // per-user children of a changed/removed parent are stopped with it
  }

  /** Lazily materializes the per-user instance for credentialMode:'per-user' servers. */
  async lease(name: string, principal: Principal): Promise<UpstreamServer>;
  shared(name: string): UpstreamServer | undefined;   // catalog/discovery always uses this one
  list(): UpstreamServer[];
  shutdown(): Promise<void>;
}

// packages/core/src/semaphore.ts — 40 LOC, gates BOTH startup connects and per-server calls.
export class Semaphore {
  constructor(private n: number);
  async run<T>(fn: () => Promise<T>, deadlineMs?: number): Promise<T>;  // try/finally release
}

// packages/core/src/catalog.ts — the ONLY place a name is built or taken apart.
export function label(sel: ServerSelection): string { return sel.alias ?? sel.serverName; }

export function project(sel: ServerSelection, bare: string, flatten: boolean): string {
  return flatten ? bare : `${label(sel)}${SEP}${bare}`;
}

/** THE predicate. Three layers, one function, called by BOTH list and call. */
export function isExposed(
  srv: UpstreamServer,
  cfg: ServerConfig,
  sel: ServerSelection,
  kind: 'tool' | 'prompt' | 'resource',
  bare: string,
): boolean {
  if (!cfg.enabled) return false;                                   // layer 1: server
  if (kind === 'tool' && cfg.tools?.[bare]?.enabled === false) return false; // layer 2: per-tool
  const allow = sel[kind === 'tool' ? 'tools' : kind === 'prompt' ? 'prompts' : 'resources'];
  if (allow !== 'all' && !allow.includes(bare)) return false;       // layer 3: scope allowlist
  return srv.catalog?.[kind === 'tool' ? 'tools' : 'prompts'].has(bare) ?? false;
}

/** THE resolver. The ONLY construction site of ToolUnavailableError. */
export function resolveTool(
  scope: ResolvedScope, reg: ServerRegistry, name: string,
): { sel: ServerSelection; bare: string } {
  for (const sel of scope.servers) {
    const bare = scope.flatten
      ? name
      : name.startsWith(label(sel) + SEP) ? name.slice(label(sel).length + SEP.length) : null;
    if (bare === null) continue;
    const srv = reg.shared(sel.serverName);
    if (srv && isExposed(srv, srv.config, sel, 'tool', bare)) return { sel, bare };
  }
  throw new ToolUnavailableError(name);            // identical text for hidden / missing / disabled
}

/** Memoized on `${scope.key}:${reg.catalogVersion}`; one Map, one entry per live scope. */
export function projectTools(scope: ResolvedScope, reg: ServerRegistry): Tool[];

// packages/core/src/bus.ts
export type EngineEvents = {
  'server:state':   { name: string; key: string; from: State; to: State;
                      attempt: number; error?: { code: string; message: string };
                      authorizationUrl?: string };
  'server:catalog': { name: string; changed: boolean; tools: number; prompts: number;
                      resources: number; fetchedAt: number };
  'call:start':     { callId: string; server: string; kind: 'tool'|'prompt'|'resource';
                      target: string; principalId: string; scopeKey: string;
                      args: unknown };                       // BY REFERENCE. Do not retain or mutate.
  'call:end':       { callId: string; ok: boolean; isError: boolean; durationMs: number;
                      errorCode?: string; result?: unknown };
  'upstream:log':   { name: string; stream: 'stderr' | 'mcp'; level: string; message: string };
  'config:applied': { generation: number; added: string[]; changed: string[]; removed: string[] };
};

export class Bus<E extends Record<string, unknown>> {
  on<K extends keyof E>(k: K, fn: (e: E[K]) => void): () => void;   // returns unsubscribe
  emit<K extends keyof E>(k: K, e: E[K]): void;
}

// packages/core/src/errors.ts — every error crossing the core boundary is one of these.
export class ToolUnavailableError extends Error {
  readonly code = 'TOOL_UNAVAILABLE';
  constructor(name: string) { super(`Tool not found: ${name}`); }   // ONE template string, ONE site
}
export class UpstreamUnavailableError extends Error {   // server failed/disabled/deadline exceeded
  readonly code = 'UPSTREAM_UNAVAILABLE';
  constructor(readonly server: string, readonly state: State, cause?: Error);
}
export class UpstreamAuthRequiredError extends Error {
  readonly code = 'UPSTREAM_AUTH_REQUIRED';
  constructor(readonly server: string, readonly authorizationUrl?: string);
}
export class CredentialsRequiredError extends Error { readonly code = 'CREDENTIALS_REQUIRED'; }
export class UpstreamBusyError extends Error { readonly code = 'UPSTREAM_BUSY'; }
export class PayloadTooLargeError extends Error { readonly code = 'PAYLOAD_TOO_LARGE'; }
export class UnsafeUrlError extends Error { readonly code = 'UNSAFE_URL'; }

/** Applied to EVERY error leaving core. Strips any resolved credential value verbatim. */
export function redact(err: Error, secrets: readonly string[]): Error;

// packages/core/src/transport.ts
export type TransportFactory = (
  cfg: ServerConfig,
  ctx: { headers: Record<string, string>;         // config headers + resolved per-user headers
         authProvider?: OAuthClientProvider;
         signal: AbortSignal;                     // aborted on stop() mid-connect
         onStderr: (line: string) => void },
) => Promise<Transport>;                          // SDK Transport, nothing narrower

export const createTransport: TransportFactory = async (cfg, ctx) => {
  switch (cfg.type) {
    case 'stdio':
      return new StdioClientTransport({
        command: cfg.command, args: expandAll(cfg.args ?? []),   // shell:false => expansion is inert
        env: { ...augmentPath(getDefaultEnvironment()), ...expandEnv(cfg.env) },
        cwd: cfg.cwd, stderr: 'pipe',
      });                                          // + detached:true, kill(-pid) on teardown
    case 'streamable-http':
      await assertSafeUrl(cfg.url, cfg.allowPrivateNetwork);
      return new StreamableHTTPClientTransport(new URL(cfg.url), {
        requestInit: { headers: ctx.headers }, authProvider: ctx.authProvider,
        fetch: guardedFetch(cfg.allowPrivateNetwork),            // validates EVERY redirect hop
      });
    case 'sse':
      await assertSafeUrl(cfg.url, cfg.allowPrivateNetwork);
      return new SSEClientTransport(new URL(cfg.url), {
        requestInit: { headers: ctx.headers }, authProvider: ctx.authProvider,
        fetch: guardedFetch(cfg.allowPrivateNetwork),
      });
  }
};

// packages/core/src/ssrf.ts
export async function assertSafeUrl(url: string, allowPrivate?: boolean): Promise<void>;
export function guardedFetch(allowPrivate?: boolean): typeof fetch;  // redirect:'manual', max 5 hops

